#include <iomanip>
#include <iostream>
struct Employee { double hours; double hourly_rate; };
double pay(const Employee& e) {
    const double regular = e.hours < 40.0 ? e.hours : 40.0;
    const double overtime = e.hours > 40.0 ? e.hours - 40.0 : 0.0;
    return regular * e.hourly_rate + overtime * e.hourly_rate * 1.5;
}
int main() { const Employee e{42.0, 20.0}; std::cout << std::fixed << std::setprecision(2) << pay(e) << '\n'; }
